export const VERSION=2;
export function fresh(){return {version:VERSION,started:false,stage:'meet',seconds:480,funds:2000,trust:3,fuse:false,repaired:false,evidence:false,decision:null,stolen:false,vouched:false,promised:false,donation:false,announced:false,position:[0,31],yaw:0,stamina:100,record:[]};}
export function transition(state,event){const s=structuredClone(state);let error='';const log=t=>s.record.unshift(t);switch(event){
 case 'meet':if(s.stage!=='meet')return {state,error:'You already spoke to Teni.'};s.stage='fuse';log('Teni needs a replacement fuse from Bisi’s market.');break;
 case 'buy':if(s.stage!=='fuse'||s.fuse||s.funds<1500)return {state,error:'You cannot buy a fuse right now.'};s.funds-=1500;s.fuse=true;s.stage='repair';log('You bought the replacement fuse from Bisi.');break;
 case 'steal':if(s.stage!=='fuse'||s.fuse)return {state,error:'There is nothing to take.'};s.fuse=true;s.stolen=true;s.trust--;s.stage='repair';log('You took the fuse. The council guard is looking for you.');break;
 case 'borrow':if(s.stage!=='fuse'||s.fuse||!s.vouched)return {state,error:'You need Musa’s guarantee first.'};s.fuse=true;s.stage='repair';s.trust++;log('Bisi accepted Musa’s guarantee. You owe the market a favour.');break;
 case 'caught':if(!s.stolen||!s.fuse||s.repaired)return {state,error:'No stolen fuse to recover.'};s.fuse=false;s.stolen=false;s.stage='fuse';log('The guard recovered the fuse. Return to Bisi and make another arrangement.');break;
 case 'repair':if(s.stage!=='repair'||!s.fuse||s.repaired)return {state,error:'Bring the replacement fuse first.'};s.repaired=true;s.fuse=false;s.stage='choose';log('The feeder is repaired. Its remaining capacity still cannot cover every request.');break;
 case 'evidence':if(s.evidence||s.announced)return {state,error:'You already have the record.'};s.evidence=true;log('The council’s private connection is taking power from the public feeder.');break;
 case 'vouch':if(s.vouched)return {state,error:'Musa has already offered his guarantee.'};s.vouched=true;log('Musa will guarantee the fuse if you cannot pay Bisi.');break;
 case 'promise':if(s.promised)return {state,error:'You have already made that promise.'};s.promised=true;log('You promised Dr. Sade you would protect the clinic.');break;
 case 'donate':if(s.donation)return {state,error:'The residents have already contributed.'};s.donation=true;s.funds+=500;log('The compounds contributed ₦500 towards the repair.');break;
 case 'care':case 'council':case 'expose':if(s.stage!=='choose'||!s.repaired)return {state,error:'Repair the feeder before setting its priority.'};if(event==='expose'&&!s.evidence)return {state,error:'You need the council record before disconnecting the diversion.'};s.decision=event;s.stage='announce';s.trust+=event==='council'?-2:2;if(event==='council')s.funds+=3000;log(event==='care'?'You protected the clinic and compounds. The market will lose its evening power.':event==='council'?'You kept the council and market online. The clinic loses its supply.':'You disconnected the council diversion. Public services stay on, but Dairo will retaliate.');break;
 case 'announce':if(s.stage!=='announce'||!s.decision)return {state,error:'Set the feeder priority before making an announcement.'};s.announced=true;s.stage='end';if(s.promised&&s.decision==='council')s.trust-=2;log('You made your decision public in the community square.');break;
 case 'timeout':if(s.stage==='end')return {state,error:'The evening has already ended.'};s.stage='end';s.seconds=0;s.decision='blackout';break;
 default:error='Unknown choice.';
 }return {state:error?state:s,error};}
export function goal(s){return {meet:{title:'Meet the neighbourhood technician',detail:'Find Teni beside the substation.',target:'teni'},fuse:{title:'Find a replacement fuse',detail:s.vouched?'Bisi will accept Musa’s guarantee.':'Speak to Bisi at the market. You have ₦'+s.funds.toLocaleString('en-NG')+'.',target:'market'},repair:{title:'Bring the feeder back',detail:'Take the fuse to the substation and install it.',target:'station'},choose:{title:'Decide who gets the light',detail:s.evidence?'You have proof of the council diversion.':'Set the feeder controls. The council records may offer another way.',target:'board'},announce:{title:'Face the neighbourhood',detail:'Make your decision public in the community square.',target:'square'},end:{title:'The evening is over',detail:'Your choices stay with the neighbourhood.',target:'square'}}[s.stage];}
export function outcome(s){const type=s.decision;return {title:type==='expose'?'You brought the light. And made an enemy.':type==='care'?'Some lights stayed on. Some doors closed.':type==='council'?'The reception went ahead. The clinic went dark.':'Night came before the answer.',summary:type==='expose'?'The clinic, market and compounds have power. The council hall has lost its private supply. Chief Dairo now knows exactly who challenged him.':type==='care'?'Dr. Sade keeps the vaccine fridge running. Water flows in the compounds. Bisi’s traders close early and ask why their losses mattered less.':type==='council'?'Dairo thanks you with ₦3,000. The market stays open. Dr. Sade moves patients in the dark, and the neighbourhood asks what your promise was worth.':'The feeder decision was never made public in time. Nadabi faces another evening of improvised generators and unanswered questions.',trust:Math.max(0,Math.min(10,s.trust)),consequences:[s.stolen?'Bisi knows the fuse was taken. Your relationship begins with a debt.':s.vouched?'Musa put his name behind yours. He expects you to remember.':'You paid for the repair without taking a private favour.',s.evidence?'You uncovered the council’s hidden connection.':'The council’s private connection remains outside public scrutiny.',s.promised?(type==='council'?'Dr. Sade remembers the promise you broke.':'Dr. Sade remembers the promise you made.'):'You avoided making a promise to the clinic.']};}
export function recover(raw){try{const s=JSON.parse(raw),base=fresh();if(s.version!==VERSION||!['meet','fuse','repair','choose','announce','end'].includes(s.stage)||!Array.isArray(s.position)||s.position.length!==2||s.position.some(v=>!Number.isFinite(v)||Math.abs(v)>72)||!Number.isFinite(s.seconds)||s.seconds<0||s.seconds>480||!Number.isFinite(s.funds)||s.funds<0||s.funds>10000||!Number.isFinite(s.yaw)||!Array.isArray(s.record))return base;return {...base,...s,stamina:100};}catch{return fresh();}}
